const src = fs.readFileSync('/home/user/fortress/explorations/coordinator/tools/record-landing/record-landing.js', 'utf8').replace(/^export const meta/m, 'const meta')
const AF = Object.getPrototypeOf(async function () {}).constructor
const fn = new AF('args', 'agent', 'parallel', 'pipeline', 'phase', 'log', 'workflow', src)
const SORT = { counts: [{ home: 'FACTS', changes: 2 }], orientation: ['F-1'], curator: [], summary: 's' }
async function run(name, args, land, judge) {
  const calls = [], wf = []
  const agent = async (p, o) => { calls.push(o.label); if (o.label === 'sort') return SORT; if (o.label === 'judge') return judge === undefined ? 'judged' : judge
    if (o.label === 'land') { if (/undefined|NaN|\[object/.test(p)) console.log('  BAD brief renders', p.match(/undefined|NaN|\[object[^\]]*\]/)[0]); return land }; return 'ok' }
  const parallel = async (ts) => Promise.all(ts.map(t => t()))
  const workflow = async (ref, a) => { wf.push([ref, a]); return { mode: a.mode, judge: 'j' } }
  const r = await fn(args, agent, parallel, null, () => {}, () => {}, workflow)
  console.log(name + ': agents ' + calls.join(',') + '; workflow ' + JSON.stringify(wf) + '; stopped ' + (r.stopped || '-'))
}
const A = { batch: '26', base: 'aaa', landing: 'bbb' }
const ok = { landed: true, how: 'fast-forward', commits: ['c1 x', 'c2 y'], pushed: ['main', 'claude/worker-brief-fable-vnnuv8', 'blinded-fable'], facts: ['F-24', 'P-38', 'junk'], stopped: '', summary: 's' }
